                tileSize = 1024,
                tmpContext = tmpCanvas.getContext('2d'),
                subsampled,
                vertSquashRatio,
                tileX,
                tileY;
            tmpCanvas.width = tileSize;
            tmpCanvas.height = tileSize;
            context.save();
            subsampled = loadImage.detectSubsampling(img);
            if (subsampled) {
                sourceX /= 2;
                sourceY /= 2;
                sourceWidth /= 2;
                sourceHeight /= 2;
            }
            vertSquashRatio = loadImage.detectVerticalSquash(img, subsampled);
            if (subsampled || vertSquashRatio !== 1) {
                sourceY *= vertSquashRatio;
                destWidth = Math.ceil(tileSize * destWidth / sourceWidth);
                destHeight = Math.ceil(
                    tileSize * destHeight / sourceHeight / vertSquashRatio
                );
                destY = 0;
                tileY = 0;
                while (tileY < sourceHeight) {
                    destX = 0;
                    tileX = 0;
                    while (tileX < sourceWidth) {
                        tmpContext.clearRect(0, 0, tileSize, tileSize);
                        tmpContext.drawImage(
                            img,
                            sourceX,
                            sourceY,
                            sourceWidth,
                            sourceHeight,
                            -tileX,
                            -tileY,
                            sourceWidth,
                            sourceHeight
                        );
                        context.drawImage(
                            tmpCanvas,
                            0,
                            0,
                            tileSize,
                            tileSize,
                            destX,
                            destY,
                            destWidth,
                            destHeight
                        );
                        tileX += tileSize;
                        destX += destWidth;
                    }
                    tileY += tileSize;
                    destY += destHeight;
                }
                context.restore();
                return canvas;
            }
        }
        return originalRenderMethod(
            canvas,
            img,
            sourceX,
            sourceY,
            sourceWidth,
            sourceHeight,
            destX,
            destY,
            destWidth,
            destHeight
        );
    };

}));

var express = require('express');
var busboy = require('connect-busboy');
var fileApi = require('./file-api');
var app = express();

app.use(express.static('.', {index: 'index.html'}));

app.use(function (req, res, next) {
	// Enable CORS for non static files
	var origin = req.get('Origin');

	if (origin) {
		res.set({
			'Access-Control-Allow-Origin': origin,
			'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
			'Access-Control-Allow-Headers': 'Origin, X-Requested-With, Content-Range, Content-Disposition, Content-Type, X-Foo, X-Rnd',
			'Access-Control-Allow-Credentials': 'true'
		});
	}
	next();
});

var uploadPath = '/upload';

app.options(uploadPath, function (req, res) {
	res.end();
});

app.post(
	uploadPath,
	busboy({immediate: true}),	// parse post data
	fileApi(),					// prepare req.body, req.files and req.images
	function (req, res) {
		var jsonp = req.query.callback || null;

		res[jsonp ? 'jsonp' : 'json']({
			status: 200,
			statusText: 'OK',
			images: req.images,
			data: {
				HEADERS: req.headers,
				_REQUEST: req.body,
				_FILES: req.files
			}
		});
	}
);

// Export
module.exports.createServer = function (port, callback) {
	var server = app.listen(port, function () {
		var host = server.address().address;
		var port = server.address().port;

		console.log('Test server listening at http://%s:%s', host, port);

		callback(server);
	});
};

